@@ -5,12 +5,13 @@ export function ThemeToggle() {
   const { theme, setTheme } = useTheme();
-  return (<button aria-label="Toggle dark mode" onClick={() => setTheme(theme === "dark" ? "light" : "dark")}>
-      {theme === "dark" ? "Light" : "Dark"}
-    </button>);
+  return (
+    <button
+      aria-label="Toggle dark mode"
+      onClick={() => setTheme(theme === "dark" ? "light" : "dark")}
+    >
+      {theme === "dark" ? "Light" : "Dark"}
+    </button>
+  );
 }

output:
style(main): drop stale header comments for the module docstring

The hand-maintained author/date block was three years out of date;
the docstring plus git history carries the same information.

style(config): convert tabs to four-space indentation

Mixed tab/space indentation broke editors set to no-tab-width;
the whole function body is now spaces with balanced parens.

